"""Domain models for the AI Twin's outputs.Every rejection is returned as **typed data**, never as a bare exception or alog line. Three reasons this matters:#. The user must be told *why*, in words, or they will override the firewall.#. Rejection reasons are the tuning signal for every threshold in the system.   Without them there is no way to know whether the gates are too tight.#. A rejection that exists only in a log cannot be counted, and an uncounted   control is an unverified control."""from __future__ import annotationsimport mathfrom datetime import UTC, datetime, timedeltafrom enum import StrEnumfrom typing import Final, Selffrom pydantic import (    BaseModel,    ConfigDict,    Field,    computed_field,    field_validator,    model_validator,)from betdoc.domain.intelligence.account_models import (    LinkedBookmaker,    SportType,    utc_now,)__all__ = [    "ActionType",    "ForecastVerdict",    "MarketOpportunity",    "RejectionReason",    "SessionForecast",    "TwinRecommendation",    "VolatilityRegime",]_STRICT: Final[ConfigDict] = ConfigDict(    frozen=True,    extra="forbid",    validate_default=True,    revalidate_instances="never",    str_strip_whitespace=True,)class RejectionReason(StrEnum):    """Why the Twin refused a bet or a whole session.    Ordered from hardest to softest. A hard capital constraint outranks    expected value unconditionally: a positive-EV bet that breaches the daily    loss limit is still refused, because ruin is absorbing and no amount of    edge survives it.    """    DAILY_LOSS_LIMIT_REACHED = "daily_loss_limit_reached"    INSUFFICIENT_DEPLOYABLE_CAPITAL = "insufficient_deployable_capital"    OVEREXPOSURE_ON_SPORT = "overexposure_on_sport"    EXCEEDS_SINGLE_STAKE_CAP = "exceeds_single_stake_cap"    ACCOUNT_LIMITED_OR_UNAVAILABLE = "account_limited_or_unavailable"    STALE_ACCOUNT_STATE = "stale_account_state"    EXTREME_NEWS_VOLATILITY = "extreme_news_volatility"    UNRELIABLE_ENTITY_RESOLUTION = "unreliable_entity_resolution"    STALE_ODDS = "stale_odds"    NEGATIVE_EV = "negative_ev"    EV_BELOW_MINIMUM_EDGE = "ev_below_minimum_edge"    FAILS_ROBUST_EV = "fails_robust_ev"    SPORT_EXCLUDED_BY_PROFILE = "sport_excluded_by_profile"    PARLAYS_DISABLED = "parlays_disabled"    STAKE_ROUNDS_TO_ZERO = "stake_rounds_to_zero"    @property    def is_hard_capital_constraint(self) -> bool:        """Constraints that no expected value may override."""        return self in (            RejectionReason.DAILY_LOSS_LIMIT_REACHED,            RejectionReason.INSUFFICIENT_DEPLOYABLE_CAPITAL,            RejectionReason.OVEREXPOSURE_ON_SPORT,            RejectionReason.EXCEEDS_SINGLE_STAKE_CAP,        )    @property    def halts_session(self) -> bool:        """Whether this reason should stop the whole session, not just one bet."""        return self in (            RejectionReason.DAILY_LOSS_LIMIT_REACHED,            RejectionReason.ACCOUNT_LIMITED_OR_UNAVAILABLE,            RejectionReason.STALE_ACCOUNT_STATE,        )    @property    def user_message(self) -> str:        """Plain-language explanation. The firewall is only obeyed if understood."""        return {            RejectionReason.DAILY_LOSS_LIMIT_REACHED: (                "Your daily loss budget is exhausted once pending bets are "                "counted at their worst case. Trading stops until tomorrow."            ),            RejectionReason.INSUFFICIENT_DEPLOYABLE_CAPITAL: (                "Settled cash is too low to fund this stake. Money locked in "                "pending bets is not available."            ),            RejectionReason.OVEREXPOSURE_ON_SPORT: (                "You already hold your maximum permitted exposure in this "                "sport. Several small bets on one sport are one large bet."            ),            RejectionReason.EXCEEDS_SINGLE_STAKE_CAP: (                "The optimal stake exceeds your per-bet ceiling."            ),            RejectionReason.ACCOUNT_LIMITED_OR_UNAVAILABLE: (                "This bookmaker has restricted your stakes or is unreachable."            ),            RejectionReason.STALE_ACCOUNT_STATE: (                "Your balance data is too old to size a bet safely."            ),            RejectionReason.EXTREME_NEWS_VOLATILITY: (                "Unverified news has widened the outcome distribution so far "                "that no stake is justified. Wait for confirmation."            ),            RejectionReason.UNRELIABLE_ENTITY_RESOLUTION: (                "A news item could not be matched to this fixture with enough confidence to act on."            ),            RejectionReason.STALE_ODDS: ("The quoted price is too old to be trusted."),            RejectionReason.NEGATIVE_EV: ("At the fair price, this bet loses money on average."),            RejectionReason.EV_BELOW_MINIMUM_EDGE: (                "The edge is positive but too thin to survive execution costs."            ),            RejectionReason.FAILS_ROBUST_EV: (                "The edge exists only if our probability estimate is exactly "                "right. It disappears at the lower bound of that estimate."            ),            RejectionReason.SPORT_EXCLUDED_BY_PROFILE: (                "You have excluded this sport from your profile."            ),            RejectionReason.PARLAYS_DISABLED: ("Parlays are disabled in your profile."),            RejectionReason.STAKE_ROUNDS_TO_ZERO: (                "The mathematically correct stake is below one paisa."            ),        }[self]class ActionType(StrEnum):    """What the Twin is advising."""    SINGLE = "single"    PARLAY = "parlay"    HEDGE = "hedge"    PASS = "pass"    @property    def requires_stake(self) -> bool:        return self is not ActionType.PASSclass VolatilityRegime(StrEnum):    """Session-level market state, derived from composed news penalties."""    CALM = "calm"    NORMAL = "normal"    ELEVATED = "elevated"    EXTREME = "extreme"    @classmethod    def from_mean_penalty(cls, mean_penalty: float) -> VolatilityRegime:        """Bucket the mean composed uncertainty penalty into a regime.        Thresholds correspond to the stake reduction each implies: 1.25 is a        20% cut, 2.0 a halving, 4.0 a quartering. Above 4.0 the system is        effectively refusing to trade, which deserves its own label so the        user understands it is a deliberate stance and not a malfunction.        """        if mean_penalty < 1.25:            return cls.CALM        if mean_penalty < 2.0:            return cls.NORMAL        if mean_penalty < 4.0:            return cls.ELEVATED        return cls.EXTREME    @property    def implied_stake_scalar(self) -> float:        """Indicative stake multiple, for display only. Sizing uses the exact        composed penalty, never this bucketed approximation."""        return {            VolatilityRegime.CALM: 1.0,            VolatilityRegime.NORMAL: 0.6,            VolatilityRegime.ELEVATED: 0.3,            VolatilityRegime.EXTREME: 0.0,        }[self]class ForecastVerdict(StrEnum):    """Overall session stance."""    OPTIMAL = "optimal"    ACCEPTABLE = "acceptable"    CAUTION = "caution"    STAND_DOWN = "stand_down"    @property    def should_trade(self) -> bool:        return self is not ForecastVerdict.STAND_DOWNclass MarketOpportunity(BaseModel):    """A candidate bet as the math engine produced it, pre-news.    The input side of the Twin. ``fair_probability`` is expected to arrive    already devigged upstream (Shin, cross-checked against the power method),    so this model does not attempt to remove margin itself.    """    model_config = _STRICT    opportunity_id: str = Field(min_length=1, max_length=128)    bookmaker: LinkedBookmaker    sport_type: SportType    fixture_id: str = Field(min_length=1, max_length=128)    market_key: str = Field(min_length=1, max_length=128)    outcome_key: str = Field(min_length=1, max_length=64)    selection_label: str = Field(default="", max_length=256)    offered_odds: float = Field(gt=1.0, le=100_000.0)    fair_probability: float = Field(gt=0.0, lt=1.0)    is_parlay: bool = False    leg_count: int = Field(default=1, ge=1, le=20)    quoted_at: datetime = Field(default_factory=utc_now)    max_accepted_stake_paise: int | None = Field(default=None, gt=0)    @field_validator("quoted_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "quoted_at must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @model_validator(mode="after")    def _parlay_declares_its_legs(self) -> Self:        if self.is_parlay and self.leg_count < 2:            msg = f"parlay {self.opportunity_id!r} must declare at least two legs"            raise ValueError(msg)        return self    @property    def net_return_if_win(self) -> float:        """``b`` in the Kelly formulation."""        return self.offered_odds - 1.0    @property    def ev_per_unit(self) -> float:        """Expected profit per unit staked at the fair probability."""        return self.fair_probability * self.offered_odds - 1.0    @property    def full_kelly_fraction(self) -> float:        """``(p*b - q) / b``, clamped to ``[0, 1]``. Never a negative fraction."""        b = self.net_return_if_win        fraction = (self.fair_probability * b - (1.0 - self.fair_probability)) / b        return min(max(fraction, 0.0), 1.0)    @property    def return_variance(self) -> float:        """``p * q * o^2``: variance of the per-unit return.        The denominator of the mean-variance optimum ``f* = mu / sigma^2``, and        therefore the quantity a news uncertainty penalty multiplies.        """        q = 1.0 - self.fair_probability        return self.fair_probability * q * self.offered_odds**2    def age_seconds(self, *, now: datetime | None = None) -> float:        return ((now or utc_now()) - self.quoted_at).total_seconds()class TwinRecommendation(BaseModel):    """A single, mathematically justified instruction, including a refusal.    A ``PASS`` is a first-class recommendation carrying a    :class:`RejectionReason` and a stake of exactly zero. Modelling refusals as    data rather than as absence is what makes the firewall auditable: every    opportunity that entered the pipeline has a recorded verdict.    """    model_config = _STRICT    recommendation_id: str = Field(min_length=1, max_length=128)    opportunity_id: str | None = Field(default=None, max_length=128)    trace_id: str = Field(default="", max_length=64)    generated_at: datetime = Field(default_factory=utc_now)    action_type: ActionType    bookmaker: LinkedBookmaker | None = None    sport_type: SportType | None = None    selection_label: str = Field(default="", max_length=256)    suggested_stake_paise: int = Field(        ge=0, description="Exact integer paise. Floored, never rounded up."    )    target_odds: float = Field(        default=1.01,        gt=1.0,        description=(            "Minimum acceptable price. Odds are dimensionless, so float is "            "correct here; no monetary value is ever stored as a float."        ),    )    justification_string: str = Field(        min_length=1,        max_length=2_048,        description=(            "Human-readable reasoning. Present because an unexplained refusal "            "gets overridden, and an overridden firewall is not a firewall."        ),    )    rejection_reason: RejectionReason | None = None    fair_probability: float | None = Field(default=None, gt=0.0, lt=1.0)    news_adjusted_probability: float | None = Field(default=None, gt=0.0, lt=1.0)    applied_uncertainty_penalty: float = Field(default=1.0, ge=1.0)    full_kelly_fraction: float = Field(default=0.0, ge=0.0, le=1.0)    final_kelly_fraction: float = Field(default=0.0, ge=0.0, le=1.0)    expected_value_paise: int = Field(        default=0,        description="EV on the suggested stake, floored towards minus infinity.",    )    binding_constraint: str = Field(default="", max_length=128)    valid_for_seconds: float = Field(default=60.0, gt=0.0, le=3_600.0)    @field_validator("generated_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "generated_at must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @model_validator(mode="after")    def _pass_and_stake_are_mutually_exclusive(self) -> Self:        """A refusal stakes nothing; an instruction stakes something and says why.        Without this, a partially populated recommendation could carry both a        rejection reason and a positive stake, and a downstream executor would        have no defined behaviour.        """        if self.action_type is ActionType.PASS:            if self.suggested_stake_paise != 0:                msg = "a PASS recommendation must stake exactly zero"                raise ValueError(msg)            if self.rejection_reason is None:                msg = "a PASS recommendation must carry a rejection_reason"                raise ValueError(msg)            return self        if self.suggested_stake_paise <= 0:            msg = (                f"{self.action_type.value!r} requires a positive stake; use PASS "                "with a rejection_reason to decline"            )            raise ValueError(msg)        if self.rejection_reason is not None:            msg = "an actionable recommendation must not carry a rejection_reason"            raise ValueError(msg)        if self.bookmaker is None:            msg = "an actionable recommendation must name a bookmaker"            raise ValueError(msg)        if self.final_kelly_fraction > self.full_kelly_fraction + 1e-9:            msg = (                "final_kelly_fraction exceeds full Kelly, which means the "                "protective scaling was bypassed"            )            raise ValueError(msg)        return self    @computed_field  # type: ignore[prop-decorator]    @property    def expires_at(self) -> datetime:        return self.generated_at + timedelta(seconds=self.valid_for_seconds)    @property    def stake_reduction_from_news(self) -> float:        """Proportion of the stake removed by the news uncertainty penalty.        ``1 - 1/lambda``. A penalty of 4.0 reports 0.75, meaning three quarters        of the nominal stake was withheld purely because the information was        unreliable. This is the number to surface to the user, because it makes        the cost of acting on rumour concrete.        """        return 1.0 - (1.0 / self.applied_uncertainty_penalty)    def is_expired(self, *, now: datetime | None = None) -> bool:        return (now or utc_now()) >= self.expires_atclass SessionForecast(BaseModel):    """Aggregate stance for the current trading session.    Answers one question: given the market as it stands and this bettor's    policy, is today a day to deploy capital or to stand down.    """    model_config = _STRICT    forecast_id: str = Field(min_length=1, max_length=128)    generated_at: datetime = Field(default_factory=utc_now)    trace_id: str = Field(default="", max_length=64)    verdict: ForecastVerdict    volatility_regime: VolatilityRegime    opportunities_screened: int = Field(ge=0)    recommendations_issued: int = Field(ge=0)    rejections_by_reason: dict[RejectionReason, int] = Field(default_factory=dict)    total_recommended_stake_paise: int = Field(ge=0)    aggregate_expected_value_paise: int = 0    remaining_loss_budget_paise: int = Field(        ge=0,        description=(            "Daily loss limit less realized loss today less the worst case of "            "everything unsettled. Zero means stop."        ),    )    deployable_capital_paise: int = Field(ge=0)    active_news_alerts: int = Field(default=0, ge=0)    mean_uncertainty_penalty: float = Field(default=1.0, ge=1.0)    max_uncertainty_penalty: float = Field(default=1.0, ge=1.0)    warnings: tuple[str, ...] = Field(default=())    @field_validator("generated_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "generated_at must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @model_validator(mode="after")    def _counts_and_capital_are_consistent(self) -> Self:        if self.recommendations_issued > self.opportunities_screened:            msg = "more recommendations issued than opportunities screened"            raise ValueError(msg)        if sum(self.rejections_by_reason.values()) > self.opportunities_screened:            msg = "more rejections recorded than opportunities screened"            raise ValueError(msg)        if self.total_recommended_stake_paise > self.deployable_capital_paise:            msg = (                f"recommended stake {self.total_recommended_stake_paise} paise "                f"exceeds deployable capital {self.deployable_capital_paise} paise"            )            raise ValueError(msg)        if self.max_uncertainty_penalty < self.mean_uncertainty_penalty - 1e-9:            msg = "max_uncertainty_penalty is below the mean, which is impossible"            raise ValueError(msg)        if not self.verdict.should_trade and self.total_recommended_stake_paise != 0:            msg = "a STAND_DOWN verdict cannot recommend any stake"            raise ValueError(msg)        return self    @property    def capital_utilisation(self) -> float:        """Recommended stake as a fraction of deployable cash."""        if self.deployable_capital_paise == 0:            return 0.0        return self.total_recommended_stake_paise / self.deployable_capital_paise    @property    def expected_growth_rate(self) -> float:        """Crude expected log-growth proxy on the session's recommended book.        ``ln(1 + EV / capital)``, guarded against a non-positive argument. A        proxy only: the exact figure requires the joint scenario solve in        ``portfolio_kelly``, which is deliberately not duplicated here.        """        if self.deployable_capital_paise <= 0:            return 0.0        ratio = self.aggregate_expected_value_paise / self.deployable_capital_paise        return math.log1p(ratio) if ratio > -1.0 else float("-inf")    @property    def headline(self) -> str:        """One-line summary for the dashboard."""        return (            f"{self.verdict.value.upper()}: {self.recommendations_issued} of "            f"{self.opportunities_screened} opportunities cleared, "            f"{self.volatility_regime.value} volatility, "            f"{self.remaining_loss_budget_paise / 100:.2f} INR loss budget left"        )